// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerDialog, forceCollectionsFetchToFail, restoreCollectionsFetch, openUsersModule, openContentModule, retryCollectionsFetch } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(155000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));

    await restoreCollectionsFetch(page);
    await page.goto(`${baseUrl}/admin/logout`);
    await page.goto(baseUrl);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    const response0 = await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));
    expect(response0.status()).toBe(200);

    await dismissProjectOwnerDialog(page);
    await expect(page.getByRole("link", { name: "article Articles" })).toHaveCount(1);

    await forceCollectionsFetchToFail(page);
    await openUsersModule(page);
    await openContentModule(page);
    await page.waitForSelector("text=Retry");
    await expect(page.getByRole("button", { name: "Retry" })).toHaveCount(1);
    await expect(page.getByRole("link", { name: "article Articles" })).toHaveCount(0);

    await restoreCollectionsFetch(page);
    await retryCollectionsFetch(page);

    await expect(page.getByRole("link", { name: "article Articles" })).toContainText("Articles");
    await expect(page.getByRole("link", { name: "article Articles" })).toHaveCount(1);
    await expect(page.getByRole("button", { name: "Retry" })).toHaveCount(0);
    expect(pageErrors).toHaveLength(0);
});
